{"command": "cat > /tmp/gw.py <<'EOF'
import struct
def lzw(px, mincode=8):
    clear=1<<mincode; end=clear+1
    bits=mincode+1
    table={bytes([i]):clear+2+i for i in range(1<<mincode)}
    nxt=end+1
    out=[]
    w=b''
    for ch in px:
        c=w+bytes([ch])
        if c in table:
            w=c
        else:
            out.append(table[w])
            table[c]=nxt; nxt+=1
            if nxt==(1<<bits)+1 and bits<12:
                bits+=1
            elif nxt>(1<<12):
                out.append(clear); table={bytes([i]):clear+2+i for i in range(1<<mincode)}; nxt=end+1; bits=mincode+1
            w=bytes([ch])
    if w: out.append(table[w])
    out.append(end)
    buf=0; nb=0; data=bytearray()
    for c in out:
        buf |= c<<nb; nb+=bits
        while nb>=8:
            data.append(buf&0xFF); buf>>=8; nb-=8
    if nb: data.append(buf&0xFF)
    return bytes(data)

def make_gif(fname, w,h, frames, delays=None, transparent=None, gct=None, disposal=None, loop=True, subrect=None):
    out=bytearray(b'GIF89a'+struct.pack('<HHBBB',w,h,0,0,0))
    if gct: out+=struct.pack('<HBBB',0xF0,0,0)+gct  # global color table size 256
    if loop: out+=b'\x21\xFF\x0BNETSCAPE2.0\x03\x01'+struct.pack('<H',0)+b'\x00'
    for fi,f in enumerate(frames):
        out+=b'\x21\xF9\x04'+struct.pack('<H',(delays[fi] if delays else 10))
        out+=bytes([((disposal[fi] if disposal else 0)<<2)|(4 if transparent is not None else 0), transparent if transparent is not None else 0,0,0])
        x,y,fw,fh = (subrect[fi] if subrect else (0,0,w,h))
        out+=b'\x2C'+struct.pack('<HHHH',x,y,fw,fh)+b'\x00'
        out+=bytes([8])+ _chunks(lzw(f))
        out+=b'\x00'
    out+=b'\x3B'
    open(fname,'wb').write(bytes(out))

def _chunks(data):
    r=bytearray(); i=0
    while i<len(data):
        c=data[i:i+255]; r+=bytes([len(c)])+c; i+=255
    return bytes(r)
EOF
