import sys; sys.path.insert(0,'/tmp')
from gw import lzw
# decode lzw output
def dec(data, mincode=8):
    clear=1<<mincode; end=clear+1
    bits=mincode+1
    table={i:bytes([i]) for i in range(clear)}
    nxt=end+1
    buf=0; nb=0; out=bytearray()
    prev=None
    for b in data:
        buf |= b<<nb; nb+=8
        while nb>=bits:
            code=buf & ((1<<bits)-1)
            buf>>=bits; nb-=bits
            if code==clear:
                table={i:bytes([i]) for i in range(clear)}; nxt=end+1; bits=mincode+1; prev=None; continue
            if code==end: break
            if code in table:
                e=table[code]
            elif prev is not None:
                e=prev+prev[:1]
            else: raise Exception("bad")
            out+=e
            if prev is not None:
                table[nxt]=prev+e[:1]; nxt+=1
                if nxt==(1<<bits) and bits<12: bits+=1
            prev=e
    return bytes(out)
px=bytes([ (x+y)%4 for y in range(4) for x in range(4)])
d=lzw(px)
print("lzw len",len(d), list(d))
print("decoded", dec(d,8))
print("orig    ", px)
EOF"}

