import subprocess, re
def cells(fn, extra=[]):
    out=subprocess.run(['./executable','--animate','off','-c','full','-p','off','--size','16x1']+extra+[fn],capture_output=True).stdout.decode()
    res=[]
    for a,ch in re.findall(r'\x1b\[([0-9;]+)m([^\x1b]*)', out):
        if a=='0': continue
        fg=bg=None
        m=re.match(r'38;2;(\d+);(\d+);(\d+);48;2;(\d+);(\d+);(\d+)',a)
        if m: fg=int(m.group(1)); bg=int(m.group(4))
        else:
            m=re.match(r'38;2;(\d+);(\d+);(\d+)',a)
            if m: fg=int(m.group(1))
            m=re.match(r'48;2;(\d+);(\d+);(\d+)',a)
            if m: bg=int(m.group(1))
        res.append((fg if fg is not None else bg))
    return res
print("RGB ramp0..240:", cells('/tmp/lut.png')[:16])
for a in [254,253,250,200,128,64,1]:
    print("alpha",a, cells(f'/tmp/al{a}.png'))
EOF

