#include "chafa.h"
#include "help.h"
#include "loader.h"
#include "render.h"

static const char *g_progname = "chafa";

void die(const char *fmt, ...)
{
    va_list ap; char buf[4096];
    va_start(ap, fmt);
    vsnprintf(buf, sizeof buf, fmt, ap);
    va_end(ap);
    fprintf(stderr, "%s: %s\n", g_progname, buf);
    exit(2);
}

int parse_bool(const char *s, const char *what)
{
    if(!strcmp(s,"on")||!strcmp(s,"true")||!strcmp(s,"1")) return 1;
    if(!strcmp(s,"off")||!strcmp(s,"false")||!strcmp(s,"0")) return 0;
    die("%s must be one of [on, off].", what);
    return 0;
}

int parse_real(const char *s, double *out)
{
    char *end;
    const char *p=s;
    while(*p==' ') p++;
    if(!*p) return 0;
    /* fraction support */
    double v;
    if(strchr(p,'/')) {
        char buf[256]; strncpy(buf,p,255); buf[255]=0;
        char *sl=strchr(buf,'/'); *sl=0;
        double a=strtod(buf,&end); if(*end && *end!=' ') return 0;
        double b=strtod(sl+1,&end); if(*end && *end!=' ') return 0;
        if(b==0) return 0;
        v=a/b;
    } else {
