        char tag[64]; size_t l=(size_t)(p-st); if(l>63)l=63;
        memcpy(tag,st,l); tag[l]=0;
        if(!symbol_tag_known(tag)) die("Unrecognized symbol tag '%s'.", tag);
        expect_plus=0;
    }
    (void)expect_plus;
    free(o->symbols_spec);
    o->symbols_spec=strdup(s);
    o->symbols_set=1;
}

int main(int argc, char **argv)
{
    Options o;
    memset(&o,0,sizeof o);
    o.font_ratio=0.5;
    o.margin_bottom=1; o.margin_right=0;
    o.scale=4.0; o.scale_max=0;
    o.optimize=-1;
    o.relative=0; o.polite=0; o.passthrough=PASS_AUTO;
    o.clear=0; o.exact_size=2; o.fit_width=0;
    o.label=-1; o.link=-1;
    o.grid_w=-1; o.grid_h=-1; o.grid_auto=0;
    o.animate=1;
    o.duration=-1; o.duration_inf=0;
    o.speed=1.0;
    o.color_mode=-1; o.preprocess=-1; o.dither=-1;
    o.grain_w=4; o.grain_h=4; o.dither_intensity=1.0;
    o.threshold=0.0;
    o.extractor=EXTR_AVERAGE; o.color_space=CS_RGB;
    o.threads=-1; o.work=5;
    o.fg_only=0; o.invert=0;
    o.view_w=-1; o.view_h=-1; o.have_view=0;
    o.have_size=0; o.size_w=-1; o.size_h=-1;
    o.probe_timeout=-2; o.probe_mode=0;
    o.label=-1;
    o.fg_only=0;
    o.watch=0;
    o.align_h=-1; o.align_v=-1;
    o.dither_set=0; o.symbols_set=0; o.fill_set=0; o.preprocess_set=0;

    g_progname = argv[0];

    int i=1;
    /* First pass: only --help/-h/--version handled early? chafa processes in order */
    while(i<argc) {
        char *a=argv[i];
        if(a[0]=='-' && a[1]=='-') {
            char name[64]; const char *val=NULL; int has_val=0;
            const char *eq=strchr(a+2,'=');
            if(eq){ size_t l=(size_t)(eq-(a+2)); if(l>63)l=63; memcpy(name,a+2,l); name[l]=0; val=eq+1; has_val=1; }
            else { strncpy(name,a+2,63); name[63]=0; }
            const OptEnt *e=NULL;
            for(int k=0; g_opts[k].name; k++) if(!strcmp(g_opts[k].name,name)) { e=&g_opts[k]; break; }
            if(!e) die("Unknown option --%s", name);
            if(!has_val && e->arg) {
                if(i+1>=argc) die("Missing argument for --%s", name);
                val=argv[++i];
            }
            handle_long_option(&o, name, val);
            i++;
        } else if(a[0]=='-' && a[1]) {
            const char *p=a+1;
            while(*p) {
                char c=*p++;
                const OptEnt *e=NULL;
                for(int k=0; g_opts[k].name; k++) if(g_opts[k].sname==c) { e=&g_opts[k]; break; }
                if(!e) die("Unknown option -%c", c);
                if(e->arg) {
                    if(i+1>=argc) die("Missing argument for -%c", c);
                    handle_long_option(&o, e->name, argv[++i]);
                } else {
                    handle_long_option(&o, e->name, NULL);
                }
            }
            i++;
        } else {
            /* file */
            add_file(a);
            i++;
        }
    }

    finish_options(&o);
    run(&o);
    return 0;
}
