        o->font_ratio=d;
    }
    else if(!strcmp(name,"grid")) {
        if(!strcmp(val,"auto")) { o->grid_auto=1; o->grid_w=-1; o->grid_h=-1; }
        else { int w=-1,h=-1; parse_wxh(val,&w,&h,0); if((w>=0&&w<1)||(h>=0&&h<1)) die("Grid size must be at least 1x1."); o->grid_auto=0; o->grid_w=w; o->grid_h=h; }
