        o->threshold=d;
    }
    else if(!strcmp(name,"threads")) { int v; if(!parse_int(val,&v)) die("Cannot parse integer value ?%s? for --threads", val); o->threads=v; }
    else if(!strcmp(name,"work")) {
        int v; if(!parse_int(val,&v)) die("Cannot parse integer value ?%s? for -w", val);
