    else if(!strcmp(name,"glyph-file")) { if(o->n_glyph_files<64) o->glyph_files[o->n_glyph_files++]=strdup(val); }
    else if(!strcmp(name,"symbols")) parse_symbols_spec(o,val);
    else die("Unknown option --%s", name);
}

int main(int argc, char **argv)
{
    Options o;
    memset(&o,0,sizeof o);
    o.font_ratio=0.5;
    o.margin_bottom=1; o.margin_right=0;
    o.scale=4.0; o.scale_max=0;
