int parse_bool(const char *s, const char *what)
{
    if(!strcmp(s,"on")||!strcmp(s,"true")||!strcmp(s,"1")) return 1;
    if(!strcmp(s,"off")||!strcmp(s,"false")||!strcmp(s,"0")) return 0;
    die("%s must be one of [on, off].", what);
    return 0;
}

int parse_real(const char *s, double *out)
{
    char *end;
    const char *p=s;
    while(*p==' ') p++;
    if(!*p) return 0;
    double v;
    if(strchr(p,'/')) {
        char buf[256]; strncpy(buf,p,255); buf[255]=0;
        char *sl=strchr(buf,'/'); *sl=0;
        double a=strtod(buf,&end); if(end==buf) return 0;
        while(*end==' ')end++; if(*end) return 0;
        double b=strtod(sl+1,&end); if(end==sl+1) return 0;
        while(*end==' ')end++; if(*end) return 0;
        if(b==0) return 0;
        v=a/b;
    } else {
        v=strtod(p,&end);
        if(end==p) return 0;
        while(*end==' ') end++;
        if(*end) return 0;
    }
    *out=v;
    return 1;
}

int parse_int(const char *s, int *out)
{
    char *end;
    const char *p=s;
    while(*p==' ')p++;
    if(!*p) return 0;
    long v=strtol(p,&end,10);
    if(end==p) return 0;
    while(*end==' ')end++;
    if(*end) return 0;
    *out=(int)v;
    return 1;
}

static void parse_wxh(const char *s, int *w, int *h, int is_size)
{
    const char *x=strchr(s,'x');
    char a[64],b[64];
    const char *ex = is_size ? "80x25, 80x or x25" : "4x4, 4x or x4";
    const char *wh = is_size ? "Size" : "Grid size";
    if(!x) { if(!parse_int(s,w)) die("%s must be specified as [width]x[height], [width]x or x[height], e.g %s.", wh, ex);
             *h=-1; return; }
    size_t la=(size_t)(x-s); if(la>=63) la=63;
    memcpy(a,s,la); a[la]=0;
    strncpy(b,x+1,63); b[63]=0;
    if(a[0]) { if(!parse_int(a,w)) die("%s must be specified as [width]x[height], [width]x or x[height], e.g %s.", wh, ex); }
    else *w=-1;
    if(b[0]) { if(!parse_int(b,h)) die("%s must be specified as [width]x[height], [width]x or x[height], e.g %s.", wh, ex); }
    else *h=-1;
}

