/* --- file list --- */
typedef struct FileEnt { char *path; struct FileEnt *next; } FileEnt;
static FileEnt *g_files_head=NULL, *g_files_tail=NULL;
static int g_n_files=0;

void add_file(const char *path)
{
    FileEnt *f=calloc(1,sizeof *f);
    f->path=strdup(path);
    if(g_files_tail) g_files_tail->next=f; else g_files_head=f;
    g_files_tail=f;
    g_n_files++;
}

void add_files_from(const char *path, int nulsep)
{
    FILE *fp;
    if(!strcmp(path,"-")) fp=stdin;
    else {
        fp=fopen(path,"rb");
        if(!fp) die("Failed to open '%s': %s", path, strerror(errno));
    }
    char buf[8192]; size_t n=0; int c;
    while((c=fgetc(fp))!=EOF) {
        if((!nulsep && c=='\n') || (nulsep && c=='\0')) {
            if(n) { buf[n]=0; add_file(buf); n=0; }
        } else if(n<8191) buf[n++]=(char)c;
    }
    if(n) { buf[n]=0; add_file(buf); }
    if(fp!=stdin) fclose(fp);
}

static void parse_align(const char *s, Options *o)
{
    char buf[64]; strncpy(buf,s,63); buf[63]=0;
    char *comma=strchr(buf,',');
    const char *vs=NULL;
    if(comma){ *comma=0; vs=comma+1; }
    const char *hs=buf;
    if(hs[0]) {
        if(!strcmp(hs,"left")) o->align_h=0;
        else if(!strcmp(hs,"mid")) o->align_h=1;
        else if(!strcmp(hs,"right")) o->align_h=2;
        else die("Unknown alignment specifier \"%s\".", hs);
    }
    if(vs && vs[0]) {
        if(!strcmp(vs,"top")) o->align_v=0;
        else if(!strcmp(vs,"mid")) o->align_v=1;
        else if(!strcmp(vs,"bottom")) o->align_v=2;
        else die("Unknown alignment specifier \"%s\".", vs);
    }
}

static void parse_color(const char *s, Color *c, const char *what)
{
    if(!parse_color_string(s,c))
        die("Unrecognized %s color '%s'.", what, s);
}

void handle_long_option(Options *o, const char *name, const char *val)
{
    if(!strcmp(name,"help")) do_help();
    else if(!strcmp(name,"version")) do_version();
    else if(!strcmp(name,"verbose")) o->verbose++;
    else if(!strcmp(name,"files")) { if(!val) die("Missing argument for --files"); add_files_from(val,0); }
    else if(!strcmp(name,"files0")) { if(!val) die("Missing argument for --files0"); add_files_from(val,1); }
    else if(!strcmp(name,"probe")) {
        if(!strcmp(val,"auto")) o->probe_timeout=-2;
        else if(!strcmp(val,"on")) o->probe_timeout=5.0;
        else if(!strcmp(val,"off")) o->probe_timeout=-1;
        else { double d; if(!parse_real(val,&d)||d<=0) die("Probe timeout must be a positive real number or \"auto\"."); o->probe_timeout=d; }
    }
    else if(!strcmp(name,"probe-mode")) {
        if(!strcmp(val,"any")) o->probe_mode=0;
        else if(!strcmp(val,"ctty")) o->probe_mode=1;
        else if(!strcmp(val,"stdio")) o->probe_mode=2;
        else die("Probe mode must be one of [any, ctty, stdio].");
    }
    else if(!strcmp(name,"format")) {
        if(!strcmp(val,"symbols")) o->format=FMT_SYMBOLS;
        else if(!strcmp(val,"sixels")) o->format=FMT_SIXELS;
        else if(!strcmp(val,"kitty")) o->format=FMT_KITTY;
        else if(!strcmp(val,"iterm")) o->format=FMT_ITERM;
        else die("Output format given as '%s'. Must be one of [iterm, kitty, sixels, symbols].", val);
    }
    else if(!strcmp(name,"optimize")) {
        int v;
        if(!parse_int(val,&v)) die("Cannot parse integer value ?%s? for -O", val);
        if(v<0||v>9) die("Optimization level must be in the range [0-9].");
        o->optimize=v;
    }
    else if(!strcmp(name,"relative")) o->relative=parse_bool(val,"Relative positioning");
    else if(!strcmp(name,"passthrough")) {
        if(!strcmp(val,"auto")) o->passthrough=PASS_AUTO;
        else if(!strcmp(val,"none")) o->passthrough=PASS_NONE;
        else if(!strcmp(val,"screen")) o->passthrough=PASS_SCREEN;
        else if(!strcmp(val,"tmux")) o->passthrough=PASS_TMUX;
        else die("Passthrough must be one of [auto, none, screen, tmux].");
    }
    else if(!strcmp(name,"polite")) o->polite=parse_bool(val,"Polite mode");
    else if(!strcmp(name,"align")) parse_align(val,o);
    else if(!strcmp(name,"clear")) o->clear=1;
    else if(!strcmp(name,"exact-size")) {
        if(!strcmp(val,"on")) o->exact_size=1;
        else if(!strcmp(val,"off")) o->exact_size=0;
        else if(!strcmp(val,"auto")) o->exact_size=2;
        else die("Exact size selector must be one of [on, off, auto].");
    }
    else if(!strcmp(name,"fit-width")) o->fit_width=1;
    else if(!strcmp(name,"font-ratio")) {
        double d; if(!parse_real(val,&d)||d<=0) die("Font ratio must be specified as a positive real number or fraction.");
        o->font_ratio=d;
    }
    else if(!strcmp(name,"grid")) {
        if(!strcmp(val,"auto")) { o->grid_auto=1; o->grid_w=-1; o->grid_h=-1; }
        else { int w=-1,h=-1; parse_wxh(val,&w,&h,0); if((w>=0&&w<1)||(h>=0&&h<1)) die("Grid size must be at least 1x1."); o->grid_auto=0; o->grid_w=w; o->grid_h=h; }
    }
    else if(!strcmp(name,"label")) o->label=parse_bool(val,"Label mode");
    else if(!strcmp(name,"link")) {
        if(!strcmp(val,"auto")) o->link=-1;
        else o->link=parse_bool(val,"Link labels");
    }
    else if(!strcmp(name,"margin-bottom")) { int v; if(!parse_int(val,&v)) die("Cannot parse integer value ?%s? for --margin-bottom", val); o->margin_bottom=v; }
    else if(!strcmp(name,"margin-right")) { int v; if(!parse_int(val,&v)) die("Cannot parse integer value ?%s? for --margin-right", val); o->margin_right=v; }
    else if(!strcmp(name,"scale")) {
        if(!strcmp(val,"max")) { o->scale_max=1; o->scale=0; }
        else { double d; if(!parse_real(val,&d)||d<=0) die("Scale must be specified as a positive real number or fraction."); o->scale=d; o->scale_max=0; }
    }
    else if(!strcmp(name,"size")) { int w=-1,h=-1; parse_wxh(val,&w,&h,1); if((w>=0&&w<1)||(h>=0&&h<1)) die("Size must be at least 1x1."); o->have_size=1; o->size_w=w; o->size_h=h; }
    else if(!strcmp(name,"stretch")) { o->stretch=1; o->scale_max=1; o->scale=0; }
    else if(!strcmp(name,"view-size")) { int w=-1,h=-1; parse_wxh(val,&w,&h,1); o->have_view=1; o->view_w=w; o->view_h=h; }
    else if(!strcmp(name,"animate")) o->animate=parse_bool(val,"Animate mode");
    else if(!strcmp(name,"duration")) {
        if(!strcmp(val,"inf")||!strcmp(val,"infinite")) { o->duration_inf=1; o->duration_set=1; }
        else { double d; if(!parse_real(val,&d)||d<0) die("Duration must be a positive real number or fraction, \"inf\" or \"infinite\"."); o->duration=d; o->duration_set=1; }
    }
    else if(!strcmp(name,"speed")) {
        if(!strcmp(val,"max")) { o->speed=1e9; }
        else {
            double d; const char *p=val; size_t l=strlen(val);
            if(l>3 && !strcmp(val+l-3,"fps")) {
                char buf[64]; strncpy(buf,val,l-3>63?63:l-3); buf[l-3>63?63:l-3]=0;
                if(!parse_real(buf,&d)||d<=0) die("Animation speed must be either \"max\", a real multiplier, or a real framerate followed by \"fps\". It must be greater than zero.");
                o->speed=d; o->speed_fps=1;
            } else {
                if(!parse_real(val,&d)||d<=0) die("Animation speed must be either \"max\", a real multiplier, or a real framerate followed by \"fps\". It must be greater than zero.");
                o->speed=d; o->speed_fps=0;
            }
        }
    }
    else if(!strcmp(name,"watch")) o->watch=1;
    else if(!strcmp(name,"bg")) { parse_color(val,&o->bg,"background"); o->have_bg=1; }
    else if(!strcmp(name,"fg")) { parse_color(val,&o->fg,"foreground"); o->have_fg=1; }
    else if(!strcmp(name,"colors")) {
        if(!strcmp(val,"none")) o->color_mode=CM_NONE;
        else if(!strcmp(val,"2")) o->color_mode=CM_2;
        else if(!strcmp(val,"8")) o->color_mode=CM_8;
        else if(!strcmp(val,"16/8")) o->color_mode=CM_16_8;
        else if(!strcmp(val,"16")) o->color_mode=CM_16;
        else if(!strcmp(val,"240")) o->color_mode=CM_240;
        else if(!strcmp(val,"256")) o->color_mode=CM_256;
        else if(!strcmp(val,"full")) o->color_mode=CM_FULL;
        else die("Colors must be one of [none, 2, 8, 16/8, 16, 240, 256, full].");
        o->color_mode_set=1;
    }
    else if(!strcmp(name,"color-extractor")) {
        if(!strcmp(val,"average")) o->extractor=EXTR_AVERAGE;
        else if(!strcmp(val,"median")) o->extractor=EXTR_MEDIAN;
        else die("Color extractor must be one of [average, median].");
    }
    else if(!strcmp(name,"color-space")) {
        if(!strcmp(val,"rgb")) o->color_space=CS_RGB;
        else if(!strcmp(val,"din99d")) o->color_space=CS_DIN99D;
        else die("Color space must be one of [rgb, din99d].");
    }
    else if(!strcmp(name,"dither")) {
        if(!strcmp(val,"none")) o->dither=DITHER_NONE;
        else if(!strcmp(val,"ordered")) o->dither=DITHER_ORDERED;
        else if(!strcmp(val,"diffusion")) o->dither=DITHER_DIFFUSION;
        else if(!strcmp(val,"noise")) o->dither=DITHER_NOISE;
        else die("Dither must be one of [none, ordered, diffusion, noise].");
        o->dither_set=1;
    }
    else if(!strcmp(name,"dither-grain")) {
        int w=-1,h=-1; parse_wxh(val,&w,&h,0);
        if(w!=-1 && w!=1 && w!=2 && w!=4 && w!=8) die("Grain dimensions must be exactly 1, 2, 4 or 8.");
        if(h!=-1 && h!=1 && h!=2 && h!=4 && h!=8) die("Grain dimensions must be exactly 1, 2, 4 or 8.");
        o->grain_w=w<0?4:w; o->grain_h=h<0?4:h;
    }
    else if(!strcmp(name,"dither-intensity")) {
        double d; if(!parse_real(val,&d)||d<0) die("Dither intensity must be a positive real number or fraction.");
        o->dither_intensity=d;
    }
    else if(!strcmp(name,"invert")) o->invert=1;
    else if(!strcmp(name,"preprocess")) o->preprocess=parse_bool(val,"Preprocessing");
    else if(!strcmp(name,"threshold")) {
        double d; if(!parse_real(val,&d)||d<0||d>1) die("Opacity threshold must be a real number or fraction in the range [0.0-1.0].");
        o->threshold=d;
    }
    else if(!strcmp(name,"threads")) { int v; if(!parse_int(val,&v)) die("Cannot parse integer value ?%s? for --threads", val); o->threads=v; }
    else if(!strcmp(name,"work")) {
        int v; if(!parse_int(val,&v)) die("Cannot parse integer value ?%s? for -w", val);
        if(v<1||v>9) die("Work factor must be in the range [1-9].");
        o->work=v;
    }
    else if(!strcmp(name,"fg-only")) o->fg_only=1;
    else if(!strcmp(name,"fill")) { parse_symbols_spec(o,val); o->fill_spec=o->symbols_spec; o->symbols_spec=NULL; o->symbols_set=0; o->fill_set=1; }
    else if(!strcmp(name,"glyph-file")) { if(o->n_glyph_files<64) o->glyph_files[o->n_glyph_files++]=strdup(val); }
    else if(!strcmp(name,"symbols")) parse_symbols_spec(o,val);
    else die("Unknown option --%s", name);
}

int main(int argc, char **argv)
{
    Options o;
    memset(&o,0,sizeof o);
    o.font_ratio=0.5;
    o.margin_bottom=1; o.margin_right=0;
    o.scale=4.0; o.scale_max=0;
    o.optimize=-1;
    o.relative=0; o.polite=0; o.passthrough=PASS_AUTO;
    o.clear=0; o.exact_size=2; o.fit_width=0;
    o.label=-1; o.link=-1;
    o.grid_w=-1; o.grid_h=-1; o.grid_auto=0;
    o.animate=1;
    o.duration=-1; o.duration_inf=0;
    o.speed=1.0;
    o.color_mode=-1; o.preprocess=-1; o.dither=-1;
    o.grain_w=4; o.grain_h=4; o.dither_intensity=1.0;
    o.threshold=0.0;
    o.extractor=EXTR_AVERAGE; o.color_space=CS_RGB;
    o.threads=-1; o.work=5;
    o.fg_only=0; o.invert=0;
    o.view_w=-1; o.view_h=-1; o.have_view=0;
    o.have_size=0; o.size_w=-1; o.size_h=-1;
    o.probe_timeout=-2; o.probe_mode=0;
    o.watch=0;
    o.align_h=-1; o.align_v=-1;

    g_progname = argv[0];

    int i=1;
    while(i<argc) {
        char *a=argv[i];
        if(a[0]=='-' && a[1]=='-') {
            char name[64]; const char *val=NULL; int has_val=0;
            const char *eq=strchr(a+2,'=');
            if(eq){ size_t l=(size_t)(eq-(a+2)); if(l>63)l=63; memcpy(name,a+2,l); name[l]=0; val=eq+1; has_val=1; }
            else { strncpy(name,a+2,63); name[63]=0; }
            const OptEnt *e=NULL;
            for(int k=0; g_opts[k].name; k++) if(!strcmp(g_opts[k].name,name)) { e=&g_opts[k]; break; }
            if(!e) die("Unknown option --%s", name);
            if(!has_val && e->arg) {
                if(i+1>=argc) die("Missing argument for --%s", name);
                val=argv[++i];
            }
            handle_long_option(&o, name, val);
            i++;
        } else if(a[0]=='-' && a[1]) {
            const char *p=a+1;
            while(*p) {
                char c=*p++;
                const OptEnt *e=NULL;
                for(int k=0; g_opts[k].name; k++) if(g_opts[k].sname==c) { e=&g_opts[k]; break; }
                if(!e) die("Unknown option -%c", c);
                if(e->arg) {
                    if(i+1>=argc) die("Missing argument for -%c", c);
                    handle_long_option(&o, e->name, argv[++i]);
                } else {
                    handle_long_option(&o, e->name, NULL);
                }
            }
            i++;
        } else {
            add_file(a);
            i++;
        }
    }

    run(&o);
    return 0;
}
