typedef struct { int w,h,depth,ctype,interlace; } PngInfo;

static int png_sig(const unsigned char *d, size_t n)
{
    static const unsigned char sig[8]={137,'P','N','G','\r','\n',26,'\n'};
    return n>=8 && !memcmp(d,sig,8);
}

typedef struct { unsigned char *data; size_t len, cap; } Buf;
static void buf_put(Buf *b, const unsigned char *d, size_t n)
{
    if(b->len+n > b->cap){ size_t nc=b->cap?b->cap*2:1024; while(nc<b->len+n) nc*=2; b->data=realloc(b->data,nc); b->cap=nc; }
    memcpy(b->data+b->len,d,n); b->len+=n;
}

static const unsigned AD7_XSTART[7]={0,4,0,2,0,1,0};
static const unsigned AD7_YSTART[7]={0,0,4,0,2,0,1};
static const unsigned AD7_XSTEP[7]={8,8,4,4,2,2,1};
static const unsigned AD7_YSTEP[7]={8,8,8,4,4,2,2};

static int png_decode(const unsigned char *d, size_t n, Image *img)
{
    if(!png_sig(d,n)) return -1;
    PngInfo pi; memset(&pi,0,sizeof pi);
    int have_ihdr=0, have_iend=0, have_plte=0;
    unsigned char plte[256*3]; int plte_n=0;
    unsigned char trns[256]; int trns_n=0;
    unsigned trns_gray=-1, trns_rgb_r=-1,trns_rgb_g=-1,trns_rgb_b=-1;
    Buf idat={0};
    size_t p=8;
    while(p+8<=n) {
        unsigned len=(d[p]<<24)|(d[p+1]<<16)|(d[p+2]<<8)|d[p+3];
        const char *type=(const char*)d+p+4;
        if(p+12+len>n) break;
        if(!memcmp(type,"IHDR",4)) {
            if(len<13) return -1;
            pi.w=(d[p+8]<<24)|(d[p+9]<<16)|(d[p+10]<<8)|d[p+11];
            pi.h=(d[p+12]<<24)|(d[p+13]<<16)|(d[p+14]<<8)|d[p+15];
            pi.depth=d[p+16]; pi.ctype=d[p+17]; pi.interlace=d[p+16+2];
            if(pi.w<=0||pi.h<=0||pi.w>0x7fffffff/pi.h) return -1;
            have_ihdr=1;
        } else if(!memcmp(type,"PLTE",4)) {
            plte_n=len/3; if(plte_n>256) plte_n=256;
            memcpy(plte,d+p+8,plte_n*3); have_plte=1;
        } else if(!memcmp(type,"tRNS",4)) {
            if(pi.ctype==3){ trns_n=len; if(trns_n>256) trns_n=256; memcpy(trns,d+p+8,trns_n); }
            else if(pi.ctype==0 && len>=2){ trns_gray=((d[p+8]<<8)|d[p+9]); }
            else if(pi.ctype==2 && len>=6){ trns_rgb_r=(d[p+8]<<8)|d[p+9]; trns_rgb_g=(d[p+10]<<8)|d[p+11]; trns_rgb_b=(d[p+12]<<8)|d[p+13]; }
        } else if(!memcmp(type,"IDAT",4)) buf_put(&idat,d+p+8,len);
        else if(!memcmp(type,"IEND",4)){ have_iend=1; break; }
        p+=12+len;
    }
    if(!have_ihdr||!have_iend||!idat.data) { free(idat.data); return -1; }
    int channels = pi.ctype==0?1: pi.ctype==2?3: pi.ctype==3?1: pi.ctype==4?2:4;
    if(pi.ctype>6 || (pi.ctype==3 && !have_plte)) { free(idat.data); return -1; }
    if(pi.depth!=1&&pi.depth!=2&&pi.depth!=4&&pi.depth!=8&&pi.depth!=16) { free(idat.data); return -1; }

    size_t rawlen=0;
    unsigned char *raw=malloc(idat.len*3+16);
    uLongf destlen=idat.len*3+16;
    int rc=uncompress(raw,&destlen,idat.data,idat.len);
