#include "symbols.h"
#include "symtable.h"

typedef struct { const char *name; unsigned bit; } ClassEnt;
static const ClassEnt g_classes[] = {
 {"ascii",0},{"alnum",1},{"alpha",2},{"ambiguous",3},{"bad",4},{"block",5},{"border",6},
 {"braille",7},{"diagonal",8},{"digit",9},{"dot",10},{"extra",11},{"geometric",12},{"half",13},
 {"hhalf",14},{"imported",15},{"inverted",16},{"latin",17},{"legacy",18},{"narrow",19},
 {"none",20},{"quad",21},{"sextant",22},{"solid",23},{"space",24},{"stipple",25},{"technical",26},
 {"ugly",27},{"vhalf",28},{"wedge",29},{"wide",30},
 {0,0}
};

int symbol_tag_known(const char *tag)
{
    for(int i=0; g_classes[i].name; i++) if(!strcmp(g_classes[i].name,tag)) return 1;
    return 0;
}

/* Parse a spec like "block+border-diagonal" into a class mask.
   Returns 0 ok, -1 syntax error, -2 unknown tag (with tag in tagout) */
int sym_parse_spec(const char *spec, unsigned char *mask, char *tagout)
{
    unsigned bits=0;
    const char *p=spec;
    if(!*p) return -1;
    int have=0;
    while(*p) {
        int sign=1;
        if(*p=='+'||*p=='-'){ if(*p=='-') sign=0; p++; if(!*p) return -1; }
        const char *st=p;
        while(*p && *p!='+' && *p!='-') p++;
        if(p==st) return -1;
        char tag[64]; size_t l=(size_t)(p-st); if(l>63) l=63;
        memcpy(tag,st,l); tag[l]=0;
        int found=0;
        if(!strcmp(tag,"all")) {
            if(sign) bits |= 0x7fffffffu; else bits &= ~0x7fffffffu;
            found=1;
        } else {
            for(int i=0; g_classes[i].name; i++)
                if(!strcmp(g_classes[i].name,tag)){ if(sign) bits|=1u<<g_classes[i].bit; else bits&=~(1u<<g_classes[i].bit); found=1; break; }
        }
        if(!found){ if(tagout) strcpy(tagout,tag); return -2; }
        have=1;
    }
    if(!have) return -1;
    mask[0]=bits&0xff; mask[1]=(bits>>8)&0xff; mask[2]=(bits>>16)&0xff; mask[3]=(bits>>24)&0xff;
    return 0;
}

void sym_build_set(const unsigned char *mask, int **out, int *n)
{
    unsigned bits = mask[0]|(mask[1]<<8)|(mask[2]<<16)|((unsigned)mask[3]<<24);
    int *list=malloc(sizeof(int)*(sym_count()+1));
    int k=0;
    for(unsigned i=0;i<sym_count();i++){
        if(sym_table[i].classes & bits) list[k++]=i;
    }
    /* ensure space is always available */
    *out=list; *n=k;
}
