cat > /workspace/src/palette.c <<'CEOF'
#include "palette.h"

static const Color g_ansi16[16]={
 {0,0,0,255},{128,0,0,255},{0,128,0,255},{128,128,0,255},
 {0,0,128,255},{128,0,128,255},{0,128,128,255},{128,128,128,255},
 {64,64,64,255},{255,0,0,255},{0,255,0,255},{255,255,0,255},
 {0,0,255,255},{255,0,255,255},{0,255,255,255},{255,255,255,255}
};

int palette_build(int cm, const Color *fg, const Color *bg, Color *pal, int maxpal, int *ansi_idx)
{
    int n=0;
    switch(cm){
    case CM_NONE: return 0;
    case CM_2:
        pal[n++]= fg?*fg:(Color){255,255,255,255};
        pal[n++]= bg?*bg:(Color){0,0,0,255};
        if(ansi_idx){ansi_idx[0]=-1;ansi_idx[1]=-1;}
        return n;
    case CM_8: for(int i=0;i<8;i++) pal[n++]=g_ansi16[i]; break;
    case CM_16: case CM_16_8: for(int i=0;i<16;i++) pal[n++]=g_ansi16[i]; break;
    case CM_240: case CM_256: {
        for(int i=0;i<16;i++){ if(cm==CM_240 && i>0) continue; pal[n++]=g_ansi16[i]; if(ansi_idx)ansi_idx[n-1]=i; }
        if(ansi_idx && cm==CM_240) n=0;
        if(cm==CM_256){ for(int i=0;i<16;i++){ pal[n]=g_ansi16[i]; if(ansi_idx)ansi_idx[n]=i; n++; } }
        else { n=0; }
        /* 6x6x6 cube: levels 0,95,135,175,215,255 */
        static const int lv[6]={0,95,135,175,215,255};
        for(int r=0;r<6;r++) for(int g=0;g<6;g++) for(int b=0;b<6;b++){
            int idx=16 + r*36 + g*6 + b;
            if(cm==CM_240){ (void)idx; }
            pal[n].r=lv[r]; pal[n].g=lv[g]; pal[n].b=lv[b]; pal[n].a=255;
            if(ansi_idx)ansi_idx[n]=idx;
            n++;
        }
        /* grayscale 232..255 : 8 + 10*i */
        for(int i=0;i<24;i++){
            int idx=232+i;
            pal[n].r=pal[n].g=pal[n].b= 8+10*i; pal[n].a=255;
            if(ansi_idx)ansi_idx[n]=idx;
            n++;
        }
        break;
    }
    case CM_FULL: return 0;
    }
    return n;
}

double color_dist2(const Color *a, const Color *b)
{
    int dr=a->r-b->r, dg=a->g-b->g, db=a->b-b->b;
    return (double)(dr*dr+dg*dg+db*db);
}

int palette_nearest(const Color *pal, int n, const Color *c)
{
    int best=0; double bd=1e18;
    for(int i=0;i<n;i++){
        double d=color_dist2(&pal[i],c);
        if(d<bd){bd=d;best=i;}
    }
    return best;
}
