/* ---------- scaling ---------- */
/* Bilinear sample of RGBA image at fractional coords (pixel centers) */
static void sample_bilinear(const Image *img, double x, double y, Color *out)
{
    if(x<0)x=0; if(y<0)y=0;
    if(x>img->w-1) x=img->w-1;
    if(y>img->h-1) y=img->h-1;
    int x0=(int)floor(x), y0=(int)floor(y);
    int x1=x0+1, y1=y0+1;
    if(x1>img->w-1) x1=img->w-1;
    if(y1>img->h-1) y1=img->h-1;
    double fx=x-x0, fy=y-y0;
    const Color *p00=&img->px[y0*img->w+x0], *p10=&img->px[y0*img->w+x1];
    const Color *p01=&img->px[y1*img->w+x0], *p11=&img->px[y1*img->w+x1];
    for(int c=0;c<4;c++){
        double a=p00->v[c]+(p10->v[c]-p00->v[c])*fx;
        double b=p01->v[c]+(p11->v[c]-p01->v[c])*fx;
        out->v[c]=(uint8_t)(a+(b-a)*fy+0.5);
    }
}

/* Scale image into target grid of size tw x th (sampling at cell centers) */
static void scale_image(const Image *img, Image *dst)
{
    double sx = (double)img->w/dst->w;
    double sy = (double)img->h/dst->h;
    for(int y=0;y<dst->h;y++){
        double sy0 = (y+0.5)*sy - 0.5;
        for(int x=0;x<dst->w;x++){
            double sx0 = (x+0.5)*sx - 0.5;
            Color c;
            sample_bilinear(img, sx0, sy0, &c);
            dst->px[y*dst->w+x]=c;
        }
    }
}

/* ---------- preprocessing ---------- */
static void preprocess(Image *img)
{
    int mn[3]={255,255,255}, mx[3]={0,0,0};
    for(int i=0;i<img->w*img->h;i++){
        Color *c=&img->px[i];
        for(int k=0;k<3;k++){
            int v=c->v[k];
            if(v<mn[k])mn[k]=v;
            if(v>mx[k])mx[k]=v;
        }
    }
    for(int k=0;k<3;k++){
        if(mx[k]<=mn[k]){ mn[k]=0; mx[k]=255; }
    }
    for(int i=0;i<img->w*img->h;i++){
        Color *c=&img->px[i];
        for(int k=0;k<3;k++){
            double v=(c->v[k]-mn[k])*255.0/(mx[k]-mn[k]);
            int iv=(int)(v+0.5);
            if(iv<0)iv=0; if(iv>255)iv=255;
            c->v[k]=iv;
        }
    }
}

/* ---------- dither patterns ---------- */
static void dither_ordered(unsigned char *t, int w, int h, int gw, int gh, double intensity)
{
    static const int bm4[4][4]={{0,8,2,10},{12,4,14,6},{3,11,1,9},{15,7,13,5}};
    for(int y=0;y<h;y++) for(int x=0;x<w;x++){
        int gx=(x/gw)%4, gy=(y/gh)%4;
        int m=bm4[gy][gx];
        double d=(m+0.5)/16.0-0.5;   /* -0.5..0.5 */
        for(int k=0;k<3;k++){
            double v=t[(y*w+x)*3+k]+d*255.0*intensity;
            int iv=(int)(v+0.5);
            if(iv<0)iv=0; if(iv>255)iv=255;
            t[(y*w+x)*3+k]=iv;
        }
    }
}

/* ---------- symbol selection ---------- */
typedef struct { int idx; Color fg,bg; } Pick;

static double cell_error(const unsigned char *t, const unsigned char *cov, const Color *fg, const Color *bg)
{
    double e=0;
    for(int i=0;i<SUBS;i++){
        double w=cov[i]/255.0;
        for(int k=0;k<3;k++){
            double tv=t[i*3+k];
            double rv= w*fg->v[k] + (1.0-w)*bg->v[k];
            double d=tv-rv;
            e+=d*d;
        }
    }
    return e;
}

static void pick_symbol(const unsigned char *t, const int *set, int nset,
                        const Color *pal, int npal, Pick *out)
{
    double best=1e30; int bi=0; Color bf={0,0,0,255},bb={0,0,0,255};
    for(int si=0; si<nset; si++){
        int i=set[si];
        const unsigned char *cov=g_syms[i].cov;
        if(pal){
            /* try candidate pairs from palette: darkest/brightest relevant */
            /* compute optimal continuous fg/bg first */
            double sr=0,sg=0,sb=0,sw=0, sr2=0,sg2=0,sb2=0,sw2=0;
            for(int k=0;k<SUBS;k++){
                double w=cov[k]/255.0;
                sr+=w*t[k*3]; sg+=w*t[k*3+1]; sb+=w*t[k*3+2]; sw+=w;
                sr2+=(1-w)*t[k*3]; sg2+=(1-w)*t[k*3+1]; sb2+=(1-w)*t[k*3+2]; sw2+=(1-w);
            }
            Color f,g2;
            if(sw>1e-9){ f.r=(uint8_t)(sr/sw+0.5); f.g=(uint8_t)(sg/sw+0.5); f.b=(uint8_t)(sb/sw+0.5); }
            else f=t[0],f.g=t[1],f.b=t[2];
            if(sw2>1e-9){ g2.r=(uint8_t)(sr2/sw2+0.5); g2.g=(uint8_t)(sg2/sw2+0.5); g2.b=(uint8_t)(sb2/sw2+0.5); }
            else g2=f;
            int fi=palette_nearest(pal,npal,&f);
            int gi=palette_nearest(pal,npal,&g2);
            const Color *fps[2]={&pal[fi],&pal[gi]};
            const Color *bps[2]={&pal[gi],&pal[fi]};
            for(int c=0;c<2;c++){
                double e=cell_error(t,cov,fps[c],bps[c]);
                if(e<best-1e-9){ best=e; bi=i; bf=*fps[c]; bb=*bps[c]; }
            }
        } else {
            double sr=0,sg=0,sb=0,sw=0, sr2=0,sg2=0,sb2=0,sw2=0;
            for(int k=0;k<SUBS;k++){
                double w=cov[k]/255.0;
                sr+=w*t[k*3]; sg+=w*t[k*3+1]; sb+=w*t[k*3+2]; sw+=w;
                sr2+=(1-w)*t[k*3]; sg2+=(1-w)*t[k*3+1]; sb2+=(1-w)*t[k*3+2]; sw2+=(1-w);
            }
            Color f,b;
            if(sw>1e-9){ f.r=(uint8_t)(sr/sw+0.5); f.g=(uint8_t)(sg/sw+0.5); f.b=(uint8_t)(sb/sw+0.5); } else {f.r=f.g=f.b=0;}
            if(sw2>1e-9){ b.r=(uint8_t)(sr2/sw2+0.5); b.g=(uint8_t)(sg2/sw2+0.5); b.b=(uint8_t)(sb2/sw2+0.5); } else {b=f;}
            double e=cell_error(t,cov,&f,&b);
            if(e<best-1e-9){ best=e; bi=i; bf=f; bb=b; }
        }
    }
    out->idx=bi; out->fg=bf; out->bg=bb;
}

/* ---------- encoding ---------- */
typedef struct {
    int fg_set, bg_set;
    Color fg, bg;
    int inverted;
    int has_state;
} EncState;

static int col_eq(const Color*a,const Color*b){ return a->r==b->r&&a->g==b->g&&a->b==b->b; }

static void emit_reset(FILE *f, EncState *st)
{
    fputs("\033[0m", f);
    st->has_state=0; st->inverted=0;
}

static void set_state(FILE *f, EncState *st, const Color *fg, const Color *bg, int ansi, int use7)
{
    /* try direct: emit fg code if changed, bg code if changed */
    (void)use7;
    int nf= !st->has_state || !col_eq(&st->fg,fg);
    int nb= !st->has_state || !col_eq(&st->bg,bg);
    if(!nf && !nb) return;
    fputc(0x1b,f); fputc('[',f);
    int first=1;
    if(nf){
        if(ansi>=0){ fprintf(f,"%s%d","38;5;",ansi); }
        else fprintf(f,"38;2;%d;%d;%d",fg->r,fg->g,fg->b);
        first=0;
    }
    if(nb){
        if(!first) fputc(';',f);
        if(ansi>=0) fprintf(f,"48;5;%d",ansi);
        else fprintf(f,"48;2;%d;%d;%d",bg->r,bg->g,bg->b);
    }
    fputc('m',f);
    st->fg=*fg; st->bg=*bg; st->has_state=1; st->inverted=0;
}

static void utf8_put(FILE *f, unsigned cp)
{
    if(cp<0x80) fputc(cp,f);
    else if(cp<0x800){ fputc(0xc0|(cp>>6),f); fputc(0x80|(cp&0x3f),f); }
    else if(cp<0x10000){ fputc(0xe0|(cp>>12),f); fputc(0x80|((cp>>6)&0x3f),f); fputc(0x80|(cp&0x3f),f); }
    else { fputc(0xf0|(cp>>18),f); fputc(0x80|((cp>>12)&0x3f),f); fputc(0x80|((cp>>6)&0x3f),f); fputc(0x80|(cp&0x3f),f); }
}

/* ---------- main render of one frame ---------- */
static void render_frame(Options *o, Animation *anim, int frame, int view_w, int view_h,
                         int utf8, FILE *out, int first, int last)
{
    Frame *fr=&anim->frames[frame];
    Image img; img.w=anim->w; img.h=anim->h;
    /* compose frame over canvas */
    img.px=malloc(sizeof(Color)*img.w*img.h);
    memcpy(img.px, fr->px, sizeof(Color)*img.w*img.h);

    int cw,ch,ow,oh;
    compute_layout(o, img.w, img.h, view_w, view_h, &ow, &oh, &cw, &ch);
    if(ow<1)ow=1; if(oh<1)oh=1;

    /* symbol set */
    int *set=NULL,nset=0;
    unsigned char cmask[4]={0,0,0,0};
    if(o->symbols_spec) sym_parse_spec(o->symbols_spec,cmask,NULL);
    else sym_parse_spec(utf8?"all":"ascii",cmask,NULL);
    sym_build_set(cmask,&set,&nset);
    if(nset<1){ set[0]=0; nset=1; }

    int color_mode = o->color_mode;
    if(color_mode<0) color_mode = utf8? CM_FULL : CM_NONE;
    Color pal[256]; int npal=0; int ansi[256];
    memset(ansi,-1,sizeof ansi);
    if(color_mode>=CM_2 && color_mode<=CM_256)
        npal=palette_build(color_mode, o->have_fg?&o->fg:NULL, o->have_bg?&o->bg:NULL, pal,256,ansi);

    /* scale to sub-pixel grid */
    Image tg; tg.w=ow*SUBW; tg.h=oh*SUBH;
    tg.px=malloc(sizeof(Color)*tg.w*tg.h);
    scale_image(&img,&tg);

    /* preprocessing */
    int quant = (color_mode==CM_NONE||color_mode==CM_2||color_mode==CM_8||color_mode==CM_16_8||color_mode==CM_16);
    int prep = o->preprocess>=0? o->preprocess : (quant?1:0);
    if(prep) preprocess(&tg);

    /* dither */
    unsigned char *tp=malloc(tg.w*tg.h*3);
    for(int i=0;i<tg.w*tg.h;i++){ tp[i*3]=tg.px[i].r; tp[i*3+1]=tg.px[i].g; tp[i*3+2]=tg.px[i].b; }
    int dm = o->dither>=0? o->dither : DITHER_NONE;
    if(dm==DITHER_ORDERED) dither_ordered(tp,tg.w,tg.h,o->grain_w,o->grain_h,o->dither_intensity);

    /* symbol rendering */
    EncState st; memset(&st,0,sizeof st);
    if(color_mode!=CM_NONE && !o->polite) emit_reset(out,&st);
    for(int y=0;y<oh;y++){
        if(y) fputc('\n',out);
        for(int x=0;x<ow;x++){
            unsigned char cell[SUBS*3];
            for(int sy=0;sy<SUBH;sy++)
                for(int sx=0;sx<SUBW;sx++){
                    int sxp=x*SUBW+sx, syp=y*SUBH+sy;
                    int si=(syp*tg.w+sxp)*3;
                    cell[(sy*SUBW+sx)*3]=tp[si];
                    cell[(sy*SUBW+sx)*3+1]=tp[si+1];
                    cell[(sy*SUBW+sx)*3+2]=tp[si+2];
                }
            Pick p;
            pick_symbol(cell,set,nset, npal?pal:NULL, npal, &p);
            if(color_mode!=CM_NONE){
                if(!st.has_state || o->optimize<=0) emit_reset(out,&st);
                int ansi_fg=-1,ansi_bg=-1;
                if(npal){
                    for(int i=0;i<npal;i++){ if(col_eq(&pal[i],&p.fg)) ansi_fg=ansi[i]; if(col_eq(&pal[i],&p.bg)) ansi_bg=ansi[i]; }
                }
                set_state(out,&st,&p.fg,&p.bg, npal?ansi_fg:-1, 0);
                /* also bg index */
                (void)ansi_bg;
            }
            utf8_put(out,g_syms[p.idx].cp);
        }
        if(color_mode!=CM_NONE && st.has_state) emit_reset(out,&st);
    }
    fputc('\n',out);
    free(tp); free(tg.px); free(img.px); free(set);
}

/* ---------- run ---------- */
void run(Options *o)
{
    g_verbose=o->verbose;
    int vw,vh,utf8,colors;
    term_detect(o,&vw,&vh,&utf8,&colors);
    (void)colors;
    if(o->have_view){
        if(o->view_w>=0) vw=o->view_w;
        if(o->view_h>=0) vh=o->view_h;
    }
    if(!g_files_head){ add_file("-"); }

    int n=0;
    for(FileEnt *f=g_files_head; f; f=f->next) n++;
    int multi = n>1;

    for(FileEnt *f=g_files_head; f; f=f->next){
        Animation anim; memset(&anim,0,sizeof anim);
        if(load_animation(f->path,&anim)!=0){
            fprintf(stderr,"%s: Failed to open '%s': Unknown file format\n", g_progname?g_progname:"chafa", f->path);
            continue;
        }
        if(multi && f!=g_files_head) fputc('\n',stdout);
        if(o->label>0){ fprintf(stdout,"%s\n",f->path); }
        int nfr = anim.n_frames;
        if(!o->animate) nfr = 1;
        render_frame(o,&anim,0,vw,vh,utf8,stdout,1,1);
        free(anim.frames);
    }
}
