/* QOI decoder */
#include "loader.h"

static int qoi_sig(const unsigned char *d, size_t n)
{ return n>=14 && !memcmp(d,"qoif",4); }

static int qoi_load(const unsigned char *d, size_t n, Image *img)
{
    if(!qoi_sig(d,n)) return -1;
    unsigned w=(d[4]<<24)|(d[5]<<16)|(d[6]<<8)|d[7];
    unsigned h=(d[8]<<24)|(d[9]<<16)|(d[10]<<8)|d[11];
    int ch=d[12];
    if(ch!=3&&ch!=4) return -1;
    if(w==0||h==0||w>0x7fffffff/h) return -1;
    img->w=w; img->h=h;
    img->px=calloc((size_t)w*h,sizeof(Color));
    Color index[64]; memset(index,0,sizeof index);
    Color cur={0,0,0,255};
    size_t p=14; int i=0; size_t total=(size_t)w*h;
    while(i<(int)total && p<n){
        unsigned char b=d[p++];
        if(b==0xFE){ cur.r=d[p++]; cur.g=d[p++]; cur.b=d[p++]; if(ch==4) cur.a=d[p++]; else cur.a=255; }
        else if(b==0xFF){ cur.r=d[p++]; cur.g=d[p++]; cur.b=d[p++]; cur.a=d[p++]; }
        else if((b&0xC0)==0x00){ int idx=b&0x3F; cur=index[idx]; }
        else if((b&0xC0)==0x40){ int dr=((b>>4)&3)-2, dg=((b>>2)&3)-2, db=(b&3)-2;
            cur.r+=dr; cur.g+=dg; cur.b+=db; if(ch==4){} else cur.a=255; }
        else if((b&0xC0)==0x80){ int vg=((b&0x3F))-32; int dr=vg+d[p] -8; int db=vg+(char)d[p+1]+8; p+=2;
            cur.r+=dr; cur.g+=vg; cur.b+=db; if(ch==4){} else cur.a=255; }
        else { int run=(b&0x3F); if(run==61){ run=61+ d[p++]; if(run==255) run+= d[p++]; } run++;
            for(int k=0;k<run && i<(int)total;k++) img->px[i++]=cur;
            continue; }
        index[(cur.r*3+cur.g*5+cur.b*7)&0x3F]=cur;
        img->px[i++]=cur;
    }
    return 0;
}
int qoi_probe(const unsigned char *d, size_t n){ return qoi_sig(d,n); }
