/* XWD (X window dump) decoder */
#include "loader.h"
static int xwd_sig(const unsigned char *d, size_t n)
{
    if(n<100) return 0;
    unsigned hs=(d[0]<<24)|(d[1]<<16)|(d[2]<<8)|d[3];
    unsigned ver=(d[4]<<24)|(d[5]<<16)|(d[6]<<8)|d[7];
    return ver==7 && hs>=88 && hs<=(unsigned)n;
}
static int xwd_load(const unsigned char *d, size_t n, Image *img)
{
    if(!xwd_sig(d,n)) return -1;
    #define U32(o) (((d[o])<<24)|((d[o+1])<<16)|((d[o+2])<<8)|d[o+3])
    unsigned hs=U32(0), depth=U32(12), w=U32(16), h=U32(20);
    unsigned visual=U32(40), ncolors=U32(76), bpl=U32(36);
    (void)bpl;
    if(w==0||h==0||w>0x7fffffff/h) return -1;
    img->w=w; img->h=h;
    img->px=calloc((size_t)w*h,sizeof(Color));
    size_t off=hs;   /* after header (includes window name) */
    /* colormap entries: ncolors * 12 bytes */
    unsigned char cmap[256][3];
    if(ncolors>256) ncolors=256;
    for(unsigned i=0;i<ncolors;i++){
        unsigned r= (d[off+4]<<8)|d[off+5];
        unsigned g= (d[off+6]<<8)|d[off+7];
        unsigned b= (d[off+8]<<8)|d[off+9];
        cmap[i][0]=r>>8; cmap[i][1]=g>>8; cmap[i][2]=b>>8;
        off+=12;
    }
    for(unsigned y=0;y<h;y++){
        for(unsigned x=0;x<w;x++){
            Color c; c.a=255;
            if(depth==24||depth==32){
                c.r=d[off]; c.g=d[off+1]; c.b=d[off+2]; c.a= depth==32? d[off+3]:255;
                off += (depth==32)?4:4;
                if(depth==24 && x+1==w && bpl) { }
            } else if(depth<=8){
                unsigned idx=d[off++];
                c.r=cmap[idx][0]; c.g=cmap[idx][1]; c.b=cmap[idx][2];
            } else if(depth==16){
                unsigned v=(d[off]<<8)|d[off+1]; off+=2;
                c.r=((v>>11)&31)*255/31; c.g=((v>>5)&63)*255/63; c.b=(v&31)*255/31;
            } else { off+=4; c.r=c.g=c.b=0; }
            img->px[y*w+x]=c;
        }
    }
    return 0;
}
int xwd_probe(const unsigned char *d, size_t n){ return xwd_sig(d,n); }
