/* GIF decoder (LZW) with animation support */
#include "loader.h"

static int gif_sig(const unsigned char *d, size_t n)
{ return n>=6 && (!memcmp(d,"GIF87a",6) || !memcmp(d,"GIF89a",6)); }

typedef struct {
    const unsigned char *d; size_t n; size_t p;
    int mincode, clear, eoi;
    int codesize;
    int table[4096][2];  /* prefix, suffix */
    int lengths[4096];
    int next;
    int prev;
    unsigned buf; int bits;
    int done;
} Lzw;

static void lzw_init(Lzw *z, const unsigned char *d, size_t n, size_t p, int mincode)
{
    memset(z,0,sizeof *z);
    z->d=d; z->n=n; z->p=p;
    z->mincode=mincode; z->clear=1<<mincode; z->eoi=z->clear+1;
    z->codesize=mincode+1;
    z->next=z->eoi+1;
    for(int i=0;i<z->clear;i++){ z->table[i][0]=-1; z->table[i][1]=i; z->lengths[i]=1; }
    z->prev=-1;
}

static int lzw_read(Lzw *z)
{
    while(z->bits < z->codesize){
        if(z->p>=z->n) { z->done=1; return z->eoi; }
        z->buf |= (unsigned)z->d[z->p++] << z->bits;
        z->bits += 8;
    }
    int code = z->buf & ((1<<z->codesize)-1);
    z->buf >>= z->codesize; z->bits -= z->codesize;
    return code;
