        if(code==z->clear){ z->codesize=z->mincode+1; z->next=z->eoi+1; z->prev=-1; continue; }
        int first;
        if(code < z->next && z->lengths[code]>0){
            /* output string */
            int len=z->lengths[code];
            int tmp[4096]; int l=len;
            int c=code;
            while(c>=0 && l>0){ tmp[--l]=z->table[c][1]; c=z->table[c][0]; }
            if(l!=0) break;
            first=tmp[0];
            for(int i=0;i<len && n<maxout;i++){ out[n]=tmp[i]; if(alpha) alpha[n]=(tmp[i]==transparent)?0:255; n++; }
        } else if(z->prev>=0){
            /* KwKwK */
            int len=z->lengths[z->prev];
            int tmp[4096]; int l=len;
            int c=z->prev;
            while(c>=0 && l>0){ tmp[--l]=z->table[c][1]; c=z->table[c][0]; }
            if(l!=0) break;
            first=tmp[0];
            for(int i=0;i<len && n<maxout;i++){ out[n]=tmp[i]; if(alpha) alpha[n]=(tmp[i]==transparent)?0:255; n++; }
            if(n<maxout){ out[n]=first; if(alpha) alpha[n]=(first==transparent)?0:255; n++; }
        } else break;
