  JDIMENSION (*read_scanlines)(void*,unsigned char**,JDIMENSION) = dlsym(h,"jpeg_read_scanlines");
  int (*finish_decompress)(void*) = dlsym(h,"jpeg_finish_decompress");
  void (*destroy_decompress)(void*) = dlsym(h,"jpeg_destroy_decompress");
  void* (*alloc_small)(void*,int,size_t) = dlsym(h,"jpeg_alloc_small");
  if(!CreateDecompress||!read_header||!start_decompress||!read_scanlines||!finish_decompress||!destroy_decompress||!alloc_small){printf("dlsym fail\n");return 1;}
  static struct jpeg_decompress_struct cinfo;
  static struct jpeg_error_mgr jerr;
  memset(&cinfo,0,sizeof cinfo);
  memset(&jerr,0,sizeof jerr);
  cinfo.err=&jerr;
  CreateDecompress(&cinfo, 8, sizeof(struct jpeg_decompress_struct));
