  cinfo.out_color_space=JCS_RGB;
  int ok=start_decompress(&cinfo);
  printf("start=%d out_comps=%d out_w=%d out_h=%d\n", ok, cinfo.output_components, 0,0);
  (void)ok;
  return 0;
}
