#include <string.h>
#include <dlfcn.h>
#include <stdint.h>
typedef int boolean;
typedef unsigned int JDIMENSION;
int main(int argc,char**argv){
  void *h=dlopen("libjpeg.so.8",RTLD_NOW);
  if(!h){printf("dlopen fail\n");return 1;}
  void (*CreateDecompress)(void*,int,size_t) = dlsym(h,"jpeg_CreateDecompress");
  int (*read_header)(void*,int) = dlsym(h,"jpeg_read_header");
  int (*start_decompress)(void*) = dlsym(h,"jpeg_start_decompress");
  unsigned (*read_scanlines)(void*,unsigned char**,unsigned) = dlsym(h,"jpeg_read_scanlines");
  int (*finish_decompress)(void*) = dlsym(h,"jpeg_finish_decompress");
  void (*destroy_decompress)(void*) = dlsym(h,"jpeg_destroy_decompress");
  void (*mem_src)(void*, unsigned char*, unsigned long) = dlsym(h,"jpeg_mem_src");
  void (*calc_out)(void*) = dlsym(h,"jpeg_calc_output_dimensions");
  if(!CreateDecompress||!read_header||!start_decompress||!read_scanlines||!finish_decompress||!destroy_decompress||!mem_src||!calc_out){printf("dlsym fail\n");return 1;}
  unsigned char *ci=calloc(1,65536);
  CreateDecompress(ci, 80, 65536);
  FILE *f=fopen(argv[1],"rb");
  static unsigned char buf[1<<22]; size_t n=fread(buf,1,sizeof buf,f); fclose(f);
  mem_src(ci, buf, (unsigned long)n);
  int rc=read_header(ci, TRUE);
  printf("read_header=%d\n",rc);
  /* scan for plausible dims */
  for(size_t off=0; off<2000; off+=4){
    unsigned a=*(unsigned*)(ci+off), b=*(unsigned*)(ci+off+4);
    if(a && a<=4096 && b && b<=4096) printf("off %zu: %u x %u\n", off, a, b);
  }
  calc_out(ci);
  for(size_t off=0; off<2000; off+=4){
    unsigned a=*(unsigned*)(ci+off);
    if(a && a<=4096) printf("A off %zu: %u\n", off, a);
  }
  (void)start_decompress;(void)read_scanlines;(void)finish_decompress;(void)destroy_decompress;
  return 0;
}
EOF
