/* dlopen-based loaders: JPEG (libjpeg), WebP (libwebp), TIFF (libtiff), SVG (librsvg+cairo) */
#include "loader.h"
#include <dlfcn.h>
#include <unistd.h>

/* ---------------- JPEG ---------------- */
typedef struct { void *p[5]; int i[3]; void *tbl; int last; void *addon; int fa,la; } JErr;
static void j_err_exit(void *c){ exit(2); }

static void *g_jh=NULL;
struct JInfo { void *CreateDecompress; void *read_header; void *mem_src; void *start_decompress;
               void *read_scanlines; void *finish_decompress; void *destroy; void *std_error; };
static struct JInfo JI;

static int j_init(void)
{
    if(g_jh) return 1;
    g_jh=dlopen("libjpeg.so.8",RTLD_NOW);
    if(!g_jh) return 0;
    JI.CreateDecompress=dlsym(g_jh,"jpeg_CreateDecompress");
    JI.read_header=dlsym(g_jh,"jpeg_read_header");
    JI.mem_src=dlsym(g_jh,"jpeg_mem_src");
    JI.start_decompress=dlsym(g_jh,"jpeg_start_decompress");
    JI.read_scanlines=dlsym(g_jh,"jpeg_read_scanlines");
    JI.finish_decompress=dlsym(g_jh,"jpeg_finish_decompress");
    JI.destroy=dlsym(g_jh,"jpeg_destroy_decompress");
    JI.std_error=dlsym(g_jh,"jpeg_std_error");
    if(!JI.CreateDecompress||!JI.read_header||!JI.mem_src||!JI.start_decompress||
       !JI.read_scanlines||!JI.finish_decompress||!JI.destroy||!JI.std_error) return 0;
    return 1;
}

/* offsets within jpeg_decompress_struct (libjpeg-turbo 2.1, x86-64) */
#define JOFF_IMAGE_WIDTH 48
#define JOFF_IMAGE_HEIGHT 52
#define JOFF_NUM_COMPONENTS 56
#define JOFF_JPEG_CS 60
#define JOFF_OUT_CS 64
#define JOFF_OUT_COMPONENTS 144

static int jpeg_load_buf(unsigned char *buf, size_t n, Image *img)
{
    if(!j_init()) return -1;
    unsigned char *ci=calloc(1,65536);
    JErr *e=calloc(1,sizeof *e);
    ((void*(*)(void*))JI.std_error)(e);
    e->p[0]=j_err_exit;
    *(void**)ci=e;
    ((void(*)(void*,int,size_t))JI.CreateDecompress)(ci,80,656);
    ((void(*)(void*,unsigned char*,unsigned long))JI.mem_src)(ci,buf,(unsigned long)n);
    int rc=((int(*)(void*,int))JI.read_header)(ci,1);
    if(rc!=1){ ((void(*)(void*))JI.destroy)(ci); free(e); free(ci); return -1; }
    unsigned w=*(unsigned*)(ci+JOFF_IMAGE_WIDTH), h=*(unsigned*)(ci+JOFF_IMAGE_HEIGHT);
    if(w==0||h==0||w>65535||h>65535){ ((void(*)(void*))JI.destroy)(ci); free(e); free(ci); return -1; }
    *(int*)(ci+JOFF_OUT_CS)=2;  /* JCS_RGB */
    if(!(*(int(*)(void*))JI.start_decompress)(ci)){ ((void(*)(void*))JI.destroy)(ci); free(e); free(ci); return -1; }
    int outc=*(int*)(ci+JOFF_OUT_COMPONENTS);
    img->w=w; img->h=h;
    img->px=calloc((size_t)w*h,sizeof(Color));
    unsigned char *row=malloc((size_t)w*(size_t)(outc>0?outc:1));
    unsigned char *rows[1]; rows[0]=row;
    for(unsigned y=0;y<h;y++){
        if(!((unsigned(*)(void*,unsigned char**,unsigned))JI.read_scanlines)(ci,rows,1)) break;
        unsigned char *rp=img->px+(size_t)y*w*4;
        if(outc==3){
            for(unsigned x=0;x<w;x++){ rp[x*4]=row[x*3]; rp[x*4+1]=row[x*3+1]; rp[x*4+2]=row[x*3+2]; rp[x*4+3]=255; }
        } else if(outc==1){
            for(unsigned x=0;x<w;x++){ rp[x*4]=rp[x*4+1]=rp[x*4+2]=row[x]; rp[x*4+3]=255; }
        } else if(outc==4){
            for(unsigned x=0;x<w;x++){ rp[x*4]=row[x*4]; rp[x*4+1]=row[x*4+1]; rp[x*4+2]=row[x*4+2]; rp[x*4+3]=row[x*4+3]; }
        } else if(outc>4){
            for(unsigned x=0;x<w;x++){ rp[x*4]=row[x*outc]; rp[x*4+1]=row[x*outc+1]; rp[x*4+2]=row[x*outc+2]; rp[x*4+3]=255; }
        } else {
            memset(rp,0,(size_t)w*4);
        }
    }
    ((void(*)(void*))JI.finish_decompress)(ci);
    ((void(*)(void*))JI.destroy)(ci);
    free(row); free(e); free(ci);
    return 0;
}

/* ---------------- WebP ---------------- */
static void *g_wh=NULL;
struct WInfo { int (*GetInfo)(const uint8_t*,size_t,int*,int*); uint8_t* (*DecodeRGBA)(const uint8_t*,size_t,int*); };
static struct WInfo WI;
static int w_init(void)
{
    if(g_wh) return 1;
    g_wh=dlopen("libwebp.so.7",RTLD_NOW);
    if(!g_wh) g_wh=dlopen("libwebp.so",RTLD_NOW);
    if(!g_wh) return 0;
    WI.GetInfo=dlsym(g_wh,"WebPGetInfo");
    WI.DecodeRGBA=dlsym(g_wh,"WebPDecodeRGBA");
    return WI.GetInfo&&WI.DecodeRGBA;
}

/* ---------------- TIFF ---------------- */
static void *g_th=NULL;
struct TInfo;
static struct TInfo TI;
static int t_init(void)
{
    if(g_th) return 1;
    g_th=dlopen("libtiff.so.5",RTLD_NOW);
    if(!g_th) g_th=dlopen("libtiff.so",RTLD_NOW);
    if(!g_th) return 0;
#define TS(n) TI.n=dlsym(g_th,#n)
    TS(TIFFClientOpen); TS(TIFFClose); TS(TIFFGetField); TS(TIFFReadRGBAImageOriented);
    TS(TIFFSetField); TS(TIFFReadDirectory); TS(TIFFSetDirectory); TS(TIFFGetFieldDefaulted);
    TS(TIFFReadScanline); TS(TIFFSetErrorHandler);
#undef TS
    if(!TI.TIFFClientOpen||!TI.TIFFClose||!TI.TIFFGetField||!TI.TIFFReadRGBAImageOriented) return 0;
    return 1;
}

/* ---------------- SVG ---------------- */
static void *g_sh=NULL,*g_ch=NULL;
struct SInfo { void* (*new_from_data)(const unsigned char*, size_t, const char*);
               void (*render_document)(void*, void*, void*, void*);
               void (*free)(void*);
               void (*get_viewport)(void*, void*);
               int  (*get_intrinsic_size)(void*, double*, double*, double*, double*); };
static struct SInfo SI;
struct CInfo { void* (*surface_create)(int,int,int,int);
               void* (*create)(void*); void (*destroy)(void*);
               void (*surface_flush)(void*); void (*surface_destroy)(void*);
               unsigned char* (*surface_get_data)(void*);
               int (*surface_get_stride)(void*); int (*surface_get_width)(void*); int (*surface_get_height)(void*); };
static struct CInfo CI;
static int s_init(void)
{
    if(g_sh) return 1;
    g_sh=dlopen("librsvg-2.so.2",RTLD_NOW);
    if(!g_sh) g_sh=dlopen("librsvg-2.so",RTLD_NOW);
    if(!g_sh) return 0;
    g_ch=dlopen("libcairo.so.2",RTLD_NOW);
    if(!g_ch) return 0;
#define SS(n) SI.n=dlsym(g_sh,#n)
    SS(rsvg_handle_new_from_data); SS(rsvg_handle_render_document);
    SS(rsvg_handle_free); SS(rsvg_handle_get_viewport_size); SS(rsvg_handle_get_intrinsic_size_in_pixels);
#undef SS
#define CS(n) CI.n=dlsym(g_ch,#n)
    CS(cairo_image_surface_create); CS(cairo_create); CS(cairo_destroy);
    CS(cairo_surface_flush); CS(cairo_surface_destroy); CS(cairo_image_surface_get_data);
    CS(cairo_image_surface_get_stride); CS(cairo_image_surface_get_width); CS(cairo_image_surface_get_height);
#undef CS
    if(!SI.rsvg_handle_new_from_data||!SI.rsvg_handle_render_document||!SI.rsvg_handle_free) return 0;
    if(!CI.cairo_image_surface_create||!CI.cairo_create||!CI.cairo_destroy||!CI.cairo_image_surface_get_data) return 0;
    return 1;
}
