int webp_load_buf(unsigned char *buf, size_t n, Image *img)
{
    if(!w_init()) return -1;
    int w=0,h=0;
    if(!WI.GetInfo(buf,n,&w,&h)) return -1;
    if(w<=0||h<=0) return -1;
    int stride=0;
    uint8_t *out=WI.DecodeRGBA(buf,n,&stride);
    if(!out) return -1;
    img->w=w; img->h=h;
    img->px=calloc((size_t)w*h,sizeof(Color));
    for(int y=0;y<h;y++){
        const uint8_t *src=out+(size_t)y*stride;
        for(int x=0;x<w;x++){
            Color *c=&img->px[y*w+x];
            c->r=src[x*4]; c->g=src[x*4+1]; c->b=src[x*4+2]; c->a=src[x*4+3];
        }
    }
    return 0;
}

/* TIFF: read whole file into buffer, then use TIFFClientOpen with a memory client */
typedef struct { unsigned char *buf; size_t len; size_t pos; } TMem;
static tsize_t t_read(thandle_t h, tdata_t p, tsize_t nb)
{ TMem *m=(TMem*)h; if(m->pos+(size_t)nb>m->len) nb=(tsize_t)(m->len-m->pos); memcpy(p,m->buf+m->pos,nb); m->pos+=nb; return nb; }
static tsize_t t_write(thandle_t h, tdata_t p, tsize_t nb){ (void)h;(void)p; return nb; }
static int t_seek(thandle_t h, toff_t off, int whence)
{ TMem *m=(TMem*)h; switch(whence){case 0:m->pos=off;break;case 1:m->pos+=off;break;case 2:m->pos=m->len>off?m->len-off:0;break;} return 1; }
static int t_close(thandle_t h){ (void)h; return 0; }
static toff_t t_size(thandle_t h){ return ((TMem*)h)->len; }
static void t_map(thandle_t h, tdata_t*p, toff_t*s){(void)h;(void)p;(void)s;}
static void t_unmap(thandle_t h, tdata_t p){(void)h;(void)p;}

int tiff_probe(const unsigned char *d, size_t n)
{ if(n<4) return 0; return !memcmp(d,"II*\0",4) || !memcmp(d,"MM\0*",4); }

int tiff_load_buf(unsigned char *buf, size_t n, Image *img)
{
    if(!t_init()) return -1;
    TMem m; m.buf=buf; m.len=n; m.pos=0;
    void *tif=((void*(*)(const char*,const char*,void*(*)(thandle_t),void(*)(thandle_t),tsize_t(*)(thandle_t,tdata_t,tsize_t),
                 tsize_t(*)(thandle_t,tdata_t,tsize_t),int(*)(thandle_t,toff_t,int),int(*)(thandle_t),
                 toff_t(*)(thandle_t),void(*)(thandle_t,tdata_t,toff_t*),void(*)(thandle_t,tdata_t)))
                TI.TIFFClientOpen)("mem","rm",&m,t_read,t_write,t_seek,t_close,t_size,t_map,t_unmap);
    if(!tif) return -1;
    uint32_t w=0,h=0;
    uint32_t (*getfield)(void*,int,...) = (uint32_t(*)(void*,int,...))TI.TIFFGetField;
    getfield(tif,256,&w); getfield(tif,257,&h);
    if(w==0||h==0){ ((void(*)(void*))TI.TIFFClose)(tif); return -1; }
    img->w=w; img->h=h;
    img->px=calloc((size_t)w*h,sizeof(Color));
    ((void(*)(void*,void*,unsigned,int))TI.TIFFReadRGBAImageOriented)(tif,img->px,w*h,1 /*row order*/,0);
    ((void(*)(void*))TI.TIFFClose)(tif);
    for(size_t i=0;i<(size_t)w*h;i++){ Color c=img->px[i]; img->px[i].r=c.v[2]; img->px[i].g=c.v[1]; img->px[i].b=c.v[0]; img->px[i].a=c.v[3]; }
    return 0;
}

int svg_probe(const unsigned char *d, size_t n)
{
    size_t m=n<512?n:512;
    for(size_t i=0;i+1<m;i++) if(d[i]=='<'&&(d[i+1]=='s'||d[i+1]=='S')&&!strncasecmp((const char*)d+i+1,"svg",3)) return 1;
    for(size_t i=0;i+1<m;i++) if(d[i]=='<'&&(d[i+1]=='?'||d[i+1]=='D')) return 1;
    return 0;
}
