static unsigned char *read_file(const char *path, size_t *len)
{
    FILE *fp;
    if(!strcmp(path,"-")) fp=stdin;
    else {
        fp=fopen(path,"rb");
        if(!fp) die("Failed to open '%s': %s", path, strerror(errno));
    }
    size_t cap=65536,n=0;
    unsigned char *buf=malloc(cap);
    for(;;){
        if(n==cap){ cap*=2; buf=realloc(buf,cap); }
        size_t got=fread(buf+n,1,cap-n,fp);
        if(got==0) break;
        n+=got;
    }
    if(fp!=stdin) fclose(fp);
    *len=n;
    return buf;
}

static void image_to_anim(Image *img, Animation *anim)
{
    anim->w=img->w; anim->h=img->h; anim->n_frames=1;
    anim->frames=calloc(1,sizeof(Frame));
    anim->frames[0].px=img->px;
    anim->frames[0].delay_ms=0;
}

int load_animation(const char *path, Animation *anim)
{
    size_t n=0;
    unsigned char *buf=read_file(path,&n);
    if(n==0){ free(buf); return -1; }
    Image img; memset(&img,0,sizeof img);
    int rc=-1;
    if(png_probe(buf,n)) rc=png_load(buf,n,&img);
    if(rc && jpeg_probe(buf,n)){ unsigned char *b2=malloc(n); memcpy(b2,buf,n); rc=jpeg_load_buf_pub(b2,n,&img); free(b2); }
    if(rc && gif_probe(buf,n)){ memset(anim,0,sizeof *anim); rc=gif_load(buf,n,anim); if(rc){ if(anim->frames){for(int i=0;i<anim->n_frames;i++) free(anim->frames[i].px); free(anim->frames);} memset(anim,0,sizeof *anim);} free(buf); return rc; }
    if(rc && qoi_probe(buf,n)) rc=qoi_load(buf,n,&img);
    if(rc && xwd_probe(buf,n)) rc=xwd_load(buf,n,&img);
    if(rc && webp_probe(buf,n)){ unsigned char *b2=malloc(n); memcpy(b2,buf,n); rc=webp_load_buf(b2,n,&img); free(b2); }
    if(rc && tiff_probe(buf,n)){ unsigned char *b2=malloc(n); memcpy(b2,buf,n); rc=tiff_load_buf(b2,n,&img); free(b2); }
    if(rc && svg_probe(buf,n)){ unsigned char *b2=malloc(n); memcpy(b2,buf,n); rc=svg_load_buf(b2,n,&img); free(b2); }
    free(buf);
    if(rc) return -1;
    image_to_anim(&img,anim);
    return 0;
}

