new='''int svg_load_buf(unsigned char *buf, size_t n, Image *img)
{
    if(!s_init()) return -1;
    typedef void* (*RH)(const unsigned char*,size_t,const char*);
    typedef int (*GIS)(void*,double*,double*,double*,double*);
    typedef void* (*CSurf)(int,int,int,int);
    typedef void* (*CCr)(void*);
    typedef int (*RD)(void*,void*,void*,void*);
    void *h=((RH)SI.rsvg_handle_new_from_data)(buf,n,NULL);
    if(!h) return -1;
    double iw=0,ih=0,emw=0,emh=0;
    if(SI.rsvg_handle_get_intrinsic_size_in_pixels)
        ((GIS)SI.rsvg_handle_get_intrinsic_size_in_pixels)(h,&iw,&ih,&emw,&emh);
    if(iw<=0) iw=512; if(ih<=0) ih=512;
    if(iw>4096) iw=4096; if(ih>4096) ih=4096;
    int w=(int)ceil(iw), hh=(int)ceil(ih);
    void *surf=((CSurf)CI.cairo_image_surface_create)(0,w,hh);
    if(!surf){ SI.rsvg_handle_free(h); return -1; }
    void *cr=((CCr)CI.cairo_create)(surf);
    struct { double x,y,w,h; } rect={0,0,(double)w,(double)hh};
    ((RD)SI.rsvg_handle_render_document)(h,cr,&rect,NULL);
    ((void(*)(void*))CI.cairo_destroy)(cr);
    ((void(*)(void*))CI.cairo_surface_flush)(surf);
    unsigned char *data=CI.cairo_image_surface_get_data(surf);
    int stride=CI.cairo_image_surface_get_stride(surf);
    if(!data){ ((void(*)(void*))CI.cairo_surface_destroy)(surf); SI.rsvg_handle_free(h); return -1; }
    img->w=w; img->h=hh;
    img->px=calloc((size_t)w*hh,sizeof(Color));
    for(int y=0;y<hh;y++){
        const unsigned char *row=data+(size_t)y*stride;
        for(int x=0;x<w;x++){
            Color *c=&img->px[y*w+x];
            c->r=row[x*4+2]; c->g=row[x*4+1]; c->b=row[x*4]; c->a=row[x*4+3];
        }
    }
    ((void(*)(void*))CI.cairo_surface_destroy)(surf);
    SI.rsvg_handle_free(h);
    return 0;
}
'''
s=s[:i]+new
